<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue';
import { api } from '../api/client';
import { contract,syncBehaviors,sourceStates,upstreamStates,aftersaleTypes,m4Names,type ShipmentDetail,type AftersaleDetail } from '../domain/m4';
import M4ConfirmAction from './M4ConfirmAction.vue';
const props=defineProps<{kind:'shipment'|'source'|'supplier';targetId:string;shipment?:ShipmentDetail;aftersale?:AftersaleDetail;items?:{id:string;qty:number;paidAllocatedFen:number}[]}>();
const emit=defineEmits<{done:[]}>();
const notice=ref('');const form=reactive({qty:1,sourceVersion:1,sourceState:'SHIPPED',behavior:'NORMAL',type:'REFUND_ONLY',salesOrderItemId:'',requestedRefundFen:0,purchaseOrderId:'',supplierState:'REFUND_PENDING',refundAmountFen:0});
const event=ref(''),externalId=ref(''),tracking=ref('');
function reset(){const id=globalThis.crypto.randomUUID();event.value=`MOCK-${id}`;externalId.value=props.shipment?.externalShipmentId??props.aftersale?.sourceCaseId??`MOCK-${props.kind==='shipment'?'PKG':'CASE'}-${id}`;tracking.value=`MOCK-TRACK-${id}`;notice.value='';Object.assign(form,{qty:props.shipment?.qty??props.aftersale?.qty??1,sourceVersion:(props.shipment?.sourceVersion??props.aftersale?.sourceVersion??0)+1,sourceState:props.kind==='shipment'?'SHIPPED':'REQUESTED',behavior:'NORMAL',type:props.aftersale?.type??'REFUND_ONLY',salesOrderItemId:props.aftersale?.salesOrderItemId??props.items?.[0]?.id??'',requestedRefundFen:props.aftersale?.requestedRefundFen??0,purchaseOrderId:props.aftersale?.coordinations[0]?.purchaseOrderId??'',supplierState:'REFUND_PENDING',refundAmountFen:0});}
watch(()=>[props.targetId,props.shipment?.sourceVersion,props.aftersale?.sourceVersion,props.items],reset,{immediate:true});
const body=computed(()=>props.kind==='shipment'?{eventId:event.value,externalShipmentId:externalId.value,sourceVersion:Number(form.sourceVersion),qty:Number(form.qty),carrierCode:'MOCK_EXPRESS',trackingNumber:tracking.value,sourceState:form.sourceState,behavior:form.behavior}:props.kind==='source'?{eventId:event.value,sourceCaseId:externalId.value,type:form.type,sourceState:form.sourceState,sourceVersion:Number(form.sourceVersion),salesOrderItemId:form.salesOrderItemId,qty:Number(form.qty),requestedRefundFen:Number(form.requestedRefundFen)}:{eventId:event.value,purchaseOrderId:form.purchaseOrderId,sourceVersion:Number(form.sourceVersion),state:form.supplierState,refundAmountFen:Number(form.refundAmountFen)});
const valid=computed(()=>contract(props.kind==='shipment'?'M4ShipmentEventRequest':props.kind==='source'?'M4AftersaleEventRequest':'M4SupplierAftersaleEventRequest')(body.value));
const run=computed(()=>{const target=props.targetId;const value=JSON.parse(JSON.stringify(body.value));return (key:string)=>props.kind==='shipment'?api.simulateShipment(target,value as never,key):props.kind==='source'?api.simulateAftersale(target,value as never,key):api.simulateSupplierAftersale(target,value as never,key);});
function done(){if(!props.shipment&&!props.aftersale)reset();else event.value=`MOCK-${globalThis.crypto.randomUUID()}`;notice.value='Mock 事件已排队；请刷新查看独立权威核验结果。';emit('done');}
</script>
<template><section class="panel detail-panel" :data-testid="kind==='shipment'?'shipment-generator':kind==='supplier'?'supplier-generator':'source-generator'"><h2>{{ kind==='shipment'?(shipment?'Mock 运单修订事件':'Mock 供应商发货事件'):kind==='source'?'Mock 来源平台售后事件':'Mock 供应商售后权威状态' }}</h2><p class="help-text muted">使用内部生成的合成事件号、包裹号与运单号。仅更新 Mock 权威数据并排队；请刷新结果，不能据受理响应认定退款或回填成功。</p><form class="policy-form" @submit.prevent><label>来源版本<input v-model="form.sourceVersion" name="sourceVersion" type="number" min="1" step="1" /></label><template v-if="kind!=='supplier'"><label>数量<input v-model="form.qty" name="eventQty" type="number" min="1" max="10000" step="1" /></label><label>来源状态<select v-model="form.sourceState" name="eventSourceState"><option v-for="s in kind==='shipment'?['SHIPPED','DELIVERED','EXCEPTION']:sourceStates" :key="s" :value="s">{{ m4Names[s] }} · {{ s }}</option></select></label></template><template v-if="kind==='shipment'"><label>回填故障<select v-model="form.behavior" name="syncBehavior"><option v-for="s in syncBehaviors" :key="s" :value="s">{{ m4Names[s] }}</option></select></label><label>内部 Mock 运单<input :value="tracking" readonly /></label></template><template v-if="kind==='source'"><label>售后类型<select v-model="form.type" name="aftersaleType"><option v-for="s in aftersaleTypes" :key="s" :value="s">{{ m4Names[s] }}</option></select></label><label>销售子项<select v-model="form.salesOrderItemId" name="salesOrderItemId"><option v-if="aftersale" :value="aftersale.salesOrderItemId">{{ aftersale.salesOrderItemId }}</option><option v-for="item in items" :key="item.id" :value="item.id">{{ item.id }} · 数量 {{ item.qty }}</option></select></label><label>申请退款（整数分 CNY）<input v-model="form.requestedRefundFen" name="requestedRefundFen" type="number" min="0" step="1" /></label></template><template v-if="kind==='supplier'"><label>关联采购<select v-model="form.purchaseOrderId" name="supplierPurchaseId"><option v-for="item in aftersale?.coordinations" :key="item.id" :value="item.purchaseOrderId">{{ item.purchaseOrderId }}</option></select></label><label>供应商权威状态<select v-model="form.supplierState" name="supplierState"><option v-for="s in upstreamStates" :key="s" :value="s">{{ m4Names[s] }} · {{ s }}</option></select></label><label>供应商退款（整数分 CNY）<input v-model="form.refundAmountFen" name="refundAmountFen" type="number" min="0" step="1" /></label></template><M4ConfirmAction :context="`${targetId}:${JSON.stringify(body)}`" :label="kind==='shipment'?'审核 Mock 发货事件':kind==='source'?'审核来源售后事件':'审核供应商状态事件'" :disabled="!valid" :run="run" @done="done" /></form><p v-if="notice" class="success-note" role="status">{{ notice }}</p></section></template>
